import numpy as np
from scipy import stats
from sklearn.metrics import roc_auc_score
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Find features with significant association (p < 0.05)
    sig_features = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'clinical':
            # For clinical features, use t-test
            y0 = feats.x[feats.y == 0, i]
            y1 = feats.x[feats.y == 1, i]
            t_stat, p_val = stats.ttest_ind(y0, y1, equal_var=False)
            if p_val < 0.05:
                sig_features.append((fid, abs(t_stat), feats.y.mean() * 2 - 1))
        else:
            # For expression/copy_number, use correlation with outcome
            corr = np.corrcoef(feats.x[:, i], feats.y)[0, 1]
            if abs(corr) > 0.05:
                sig_features.append((fid, abs(corr), corr))

    # Sort by effect size
    sig_features.sort(key=lambda x: x[1], reverse=True)

    # Remove near-duplicates (correlated features)
    correlated_pairs = set()
    for i in range(len(feats.ids)):
        for j in range(i+1, len(feats.ids)):
            r = np.corrcoef(feats.x[:, i], feats.x[:, j])[0, 1]
            if abs(r) >= 0.6:
                fid1, fid2 = feats.ids[i], feats.ids[j]
                # Prefer the one with stronger association to outcome
                if (fid1, fid2) not in correlated_pairs and (fid2, fid1) not in correlated_pairs:
                    # Get effect sizes for both features
                    eff1 = None
                    eff2 = None
                    for f, _, e in sig_features:
                        if f == fid1:
                            eff1 = e
                        elif f == fid2:
                            eff2 = e
                    if eff1 is not None and eff2 is not None:
                        if abs(eff1) >= abs(eff2):
                            correlated_pairs.add((fid1, fid2))
                        else:
                            correlated_pairs.add((fid2, fid1))

    # Build driver list
    drivers = []
    used_features = set()

    # Try to find drivers using the strongest associations
    for fid, _, effect_size in sig_features:
        if len(drivers) >= MAX_DRIVERS:
            break

        # Skip if this feature is part of a correlated pair and we've already included the preferred one
        skip = False
        for pair in correlated_pairs:
            if fid in pair:
                # If we're including the other feature of the pair, skip this one
                other_fid = pair[0] if pair[1] == fid else pair[1]
                if other_fid in used_features:
                    skip = True
                    break

        if not skip:
            drivers.append(fid)
            used_features.add(fid)

    # If no strong drivers found, return empty design
    if not drivers:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Select all features with significant association for regression
    columns = tuple(fid for fid, _, _ in sig_features[:10])  # Limit to top 10

    # Add interaction terms for highly correlated pairs
    products = []
    for fid1, fid2 in correlated_pairs:
        if fid1 in columns and fid2 in columns:
            products.append((fid1, fid2))

    # Create loadings for weighted score
    loadings = {}
    for fid in columns:
        idx = feats.column(fid)
        # Use standardized coefficients from simple linear regression
        loadings[fid] = np.corrcoef(feats.x[:, idx], feats.y)[0, 1]

    # Ensure we don't exceed MAX_DRIVERS in drivers
    drivers = drivers[:MAX_DRIVERS]

    return Design(drivers=tuple(drivers), columns=columns, products=tuple(products), loadings=loadings)
